<script>const s=document.getElementById('search'),results=document.getElementById('searchResults'),allTools=<?=json_encode($searchTools,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;function esc(v){const d=document.createElement('div');d.textContent=v;return d.innerHTML}function renderSearch(){const q=s.value.trim().toLowerCase();results.innerHTML='';if(!q){results.classList.remove('open');return}const matches=allTools.filter(t=>(t.name+' '+t.description).toLowerCase().includes(q)).slice(0,15);if(!matches.length){results.innerHTML='<div class="no-result">No tools found for <strong>'+esc(s.value)+'</strong></div>';results.classList.add('open');return}matches.forEach(t=>{const a=document.createElement('a');a.className='search-result';a.href=t.url;a.innerHTML='<span class="ri"><span class="material-symbols-rounded"></span></span><span class="rt"><span class="rn"></span><span class="rd"></span></span>';a.querySelector('.ri .material-symbols-rounded').textContent=t.icon||'build';a.querySelector('.rn').textContent=t.name;a.querySelector('.rd').textContent=t.description;results.appendChild(a)});results.classList.add('open')}s.addEventListener('input',renderSearch);s.addEventListener('focus',renderSearch);document.addEventListener('click',e=>{if(!e.target.closest('.search'))results.classList.remove('open')});</script></body></html>
